# TEST 5 -- SHIELDING: neutral pair has no monopole (closed error field)
# ----------------------------------------------------------------------
def test5_shielding():
    print("\n[TEST 5] SHIELDING: neutral pair = closed error field (no monopole)")
    q, d = 1.0, 0.1
    R = np.array([10.0, 20.0, 50.0])
    phi_mono = q / (4.0 * math.pi * R)          # single charge: ~ 1/R
    phi_dip = q * d / (4.0 * math.pi * R * R)   # neutral pair (dipole): ~ 1/R^2
    ratio = phi_dip / phi_mono                  # = d/R (multipole suppression)
    print(f"   d={d}, theta=0 (aligned):")
    for i, r in enumerate(R):
        print(f"     R={r:5.0f}: |phi_mono|={abs(phi_mono[i]):.3e} (1/R), "
              f"|phi_neutral|={abs(phi_dip[i]):.3e} (1/R^2), "
              f"ratio={ratio[i]:.4f} (=d/R={d/r:.4f})")
    # field decay: monopole ~1/R^2, dipole ~1/R^3
    Fm = phi_mono / R     # |grad phi_mono| ~ 1/R^2
    Fd = phi_dip / R      # |grad phi_dip| ~ 1/R^3
    decay_m = Fm[1] / Fm[0]   # expected (R0/R1)^2
    decay_d = Fd[1] / Fd[0]   # expected (R0/R1)^3
    exp_m = (R[0] / R[1]) ** 2
    exp_d = (R[0] / R[1]) ** 3
    print(f"   field decay R=10->20: monopole {decay_m:.4f} vs 1/R^2 {exp_m:.4f}; "
          f"neutral(dipole) {decay_d:.4f} vs 1/R^3 {exp_d:.4f}")
    print("   => neutral bound system: net source 0 -> no monopole -> far field")
    print("      is CLOSED (decays 1/R^3). Ze: экранирование = замыкание потока;")
    print("      neutral matter electrically invisible at distance, still")
    print("      gravitationally visible (gravity sees total energy, not Q).")
    ok = abs(decay_d - exp_d) < 1e-3 and abs(decay_m - exp_m) < 1e-3
    print(f"   VERDICT: {'PASS' if ok else 'FAIL'}")
    return ok


