    ratio = Fg / Fe
    m_Pl = math.sqrt(hbar * c / G)
    alpha = k * e * e / (hbar * c)
    ratio2 = (m_e / m_Pl) ** 2 / alpha
    print(f"   direct:  F_grav/F_elec = {ratio:.3e}")
    print(f"   dimless: (m_e/m_Pl)^2/alpha = {ratio2:.3e}  "
          f"(m_e/m_Pl={m_e/m_Pl:.3e}, alpha={1/alpha:.2f}^-1)")
    print("   Ze reading: EM = PRIMARY photon-level coupling (alpha from the Ze")
    print("      formula alpha=P(S|v*) g/(4pi)); gravity = SECONDARY geometric")
    print("      residue, suppressed by the square of the tiny mass-to-Planck")
    print("      ratio (m_e/m_Pl)^2. The electron is 'almost massless' in Planck")
    print("      units -> its accumulated deficit couples ~10^43 times weaker.")
    ok = abs(ratio - ratio2) / ratio < 1e-3
    print(f"   VERDICT: {'PASS' if ok else 'FAIL'} (both forms agree)")
    return ok


